def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Check if in given list of numbers, are any two numbers closer to each other than given threshold.

    :param numbers: List of floating point numbers
    :param threshold: The threshold to compare the difference between numbers
    :return: True if any two numbers are closer than the threshold, False otherwise
    """
    if not all(isinstance(num, float) for num in numbers):
        raise TypeError("All elements in the list must be floats.")
    if not isinstance(threshold, float):
        raise TypeError("The threshold must be a float.")

    numbers.sort()
    for i in range(len(numbers) - 1):
        if abs(numbers[i] - numbers[i + 1]) < threshold:
            return True
    return False

