def cantor_numbering(N: int) -> str:
    if N < 1:
        raise ValueError("N must be a positive integer")

    level = 1
    while N > level:
        N -= level
        level += 1

    if level % 2 == 0:
        # Even level, goes right to left
        numerator = N
        denominator = level + 1 - N
    else:
        # Odd level, goes left to right
        numerator = level + 1 - N
        denominator = N

    return f"{numerator}/{denominator}"

