def max_energy(beads):
    n = len(beads)
    beads = beads * 2  # Duplicate to handle circular nature

    # dp[i][j] will store the max energy obtained in merging beads[i] to beads[j]
    dp = [[0] * (n * 2) for _ in range(n * 2)]

    # Fill the table in a bottom-up manner
    for length in range(2, n + 1):  # length is the distance between i and j
        for i in range(n):
            j = i + length - 1
            if j >= n * 2:
                continue
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    # The result will be the maximum energy obtained in merging any i and j where j is within the original length
    return max(dp[i][i + n - 1] for i in range(n))

