def count_partitions(n: int, k: int, x: int) -> int:
    def dp(n, k, x, memo):
        if k == 0:
            return 1 if n == 0 else 0
        if n < k * x or k < 0:
            return 0
        if (n, k, x) not in memo:
            memo[(n, k, x)] = dp(n - x, k - 1, x, memo) + dp(n, k, x + 1, memo)
        return memo[(n, k, x)]

    if n < k * x:
        return 0
    return dp(n, k, x, {})

