def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("Number of disc pairs must be at least 1.")

    # Base case for 1 pair of discs
    if n == 1:
        return 2

    # Initialize the number of moves for 1 pair
    moves = 2

    # Iteratively compute the number of moves for n pairs
    for i in range(2, n + 1):
        moves = 3 * moves + 2

    return moves

